import{_ as o,o as a,c as t,aj as i}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Migration to Control Flow syntax","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/migrations/control-flow.md","filePath":"en/reference/migrations/control-flow.md"}'),n={name:"en/reference/migrations/control-flow.md"};function r(s,e,l,c,h,d){return a(),t("div",null,e[0]||(e[0]=[i('<h1 id="migration-to-control-flow-syntax" tabindex="-1">Migration to Control Flow syntax <a class="header-anchor" href="#migration-to-control-flow-syntax" aria-label="Permalink to &quot;Migration to Control Flow syntax&quot;">​</a></h1><p><a href="/en/guide/templates/control-flow">Control flow syntax</a> is available from Angular v17. The new syntax is baked into the template, so you don&#39;t need to import <code>CommonModule</code> anymore.</p><p>This schematic migrates all existing code in your application to use new Control Flow Syntax.</p><p>Run the schematic using the following command:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/core:control-flow</span></span></code></pre></div><h2 id="configuration-options" tabindex="-1">Configuration options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to &quot;Configuration options&quot;">​</a></h2><p>The migration supports a few options for fine tuning the migration to your specific needs.</p><h3 id="path" tabindex="-1"><code>--path</code> <a class="header-anchor" href="#path" aria-label="Permalink to &quot;`--path`&quot;">​</a></h3><p>By default, the migration will update your whole Angular CLI workspace. You can limit the migration to a specific sub-directory using this option.</p><h3 id="format" tabindex="-1"><code>--format</code> <a class="header-anchor" href="#format" aria-label="Permalink to &quot;`--format`&quot;">​</a></h3><p>By default, the migration reformats the templates it touches. Disable this option to keep your existing template formatting.</p><h2 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h2><h3 id="for-view-reuse" tabindex="-1"><code>@for</code> view reuse <a class="header-anchor" href="#for-view-reuse" aria-label="Permalink to &quot;`@for` view reuse&quot;">​</a></h3><p>If a property used in the <code>track</code> expression of a <code>@for</code> block changes but the object reference remains the same (in-place modification), Angular updates the view&#39;s bindings (including component inputs) instead of destroying and recreating the element.</p><p>This differs from <code>*ngFor</code>, which would execute a remount (destroy and recreate) of the element in a similar scenario if the <code>trackBy</code> function returned a different value.</p>',15)]))}const f=o(n,[["render",r]]);export{u as __pageData,f as default};
